function learnTitle(t){if(typeof t==='string'&&t.length<60&&titleIndex.indexOf(t)<0){titleIndex.push(t);if(titleIndex.length>700)titleIndex.splice(10,1);}}
function normalized(t){return String(t||'').normalize('NFKC').trim().replace(/[《》「」]/g,'').replace(/\s+/g,' ');}
function compact(t){return normalized(t).toLowerCase().replace(/[\s·:：\-]/g,'');}
var aliases={'权游':'权力的游戏','权利的游戏':'权力的游戏','狂飚':'狂飙','新聞女王':'新闻女王','想見你':'想见你','華燈初上':'华灯初上','澳門風雲':'澳门风云','請回答1988':'请回答1988'};
function queryFor(t){var q=normalized(t);if(/[\u3400-\u9fff]/.test(q)&&!/[a-z]/i.test(q))q=q.replace(/\s+/g,'');return aliases[q]||q;}
function distance(a,b){var prev=[],next=[],i,j;for(j=0;j<=b.length;j++)prev[j]=j;for(i=1;i<=a.length;i++){next=[i];for(j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=next;}return prev[b.length];}
function suggestions(term){var q=compact(queryFor(term));if(q.length<2)return [];return titleIndex.map(function(t){var k=compact(t),d=Math.abs(q.length-k.length)<=2?distance(q,k):99;return {title:t,rank:k===q?-1:k.indexOf(q)>=0?0:d<=(q.length>=5?2:1)?d:99};}).filter(function(x){return x.rank>=0&&x.rank<99;}).sort(function(a,b){return a.rank-b.rank||a.title.length-b.title.length;}).slice(0,5);}
