function play(index){var recoveryToken=recoveryBegin(index);cancelSpeed();cachePlayState(true);liveActive=false;document.getElementById('progress').style.display='';playbackControls.stop();episode=index;qualityStart();playing=true;player.hidden=false;document.activeElement.blur();document.getElementById('play-title').textContent=group.name+' · 第 '+(index+1)+' 集 · '+detail.record.sourceName;osd('正在加载…',true);if(hls){hls.destroy();hls=null;}video.pause();video.removeAttribute('src');video.load();loading.start({live:false,title:group.name,source:'第 '+(index+1)+' 集 · '+detail.record.sourceName,poster:cover(group.cover)});var url='/api/proxy?'+(localStorage.getItem('mobile-ad-filter')==='off'?'':'adFilter=1&')+'url='+encodeURIComponent(detail.episodes[index]);if(Hls.isSupported()){hls=new Hls({enableWorker:false,maxBufferLength:30,maxMaxBufferLength:60,backBufferLength:60});hls.on(Hls.Events.ERROR,function(e,data){if(recoveryToken!==recoveryEpoch)return;if(data.fatal){if(availableItem)availability.reject(availableItem);console.log('TV_HLS_ERROR '+data.type+' '+data.details);recoveryFail('播放失败');}});if(Hls.Events.MANIFEST_PARSED)hls.on(Hls.Events.MANIFEST_PARSED,function(){if(playing&&!liveActive)loading.stage(1,'来源已连接，正在缓冲画面');});hls.loadSource(url);hls.attachMedia(video);}else video.src=url;playbackControls.start();var pending=video.play();if(pending)pending.catch(function(e){if(recoveryToken!==recoveryEpoch||e&&e.name==='AbortError')return;if(e&&e.name==='NotAllowedError'){if(recovery)recovery.intended=false;loading.fail('点击播放继续');}else recoveryFail('无法开始播放');});recoveryArmed();console.log('TV_PLAY episode='+index);}
function stop(){recoveryCancel();cancelSpeed();cachePlayState(false);loading.stop();playbackControls.stop();save();clearTimeout(liveTimer);liveTimer=null;liveToken++;liveActive=false;player.classList.remove('live-mode');liveFailed=false;playing=false;document.getElementById('progress').style.display='';video.pause();if(hls){hls.destroy();hls=null;}video.removeAttribute('src');video.load();player.hidden=true;clearTimeout(osdTimer);}
video.onloadedmetadata=function(){if(recoveryRestore())return;if(liveActive||!group)return;var previous=history().filter(function(x){return x.name===group.name&&x.episode===episode;})[0];if(previous&&previous.seconds>5&&previous.seconds<video.duration-20)video.currentTime=previous.seconds;};
video.onplaying=function(){if(liveActive){liveProgress();}osd('');};video.onwaiting=function(){if(liveActive)armLiveTimeout();if(playing)osd('正在缓冲…',true);};video.onerror=function(){if(liveActive){failLive();return;}if(playing&&availableItem)availability.reject(availableItem);if(playing)recoveryFail('播放失败');};video.onended=function(){if(recovery&&(recovery.busy||recovery.restore!==null||recovery.exhausted))return;if(liveActive){failLive();return;}save();if(episode+1<detail.episodes.length)play(episode+1);else{stop();renderDetail();}};
video.ontimeupdate=function(){if(liveActive){liveProgress();return;}document.querySelector('#progress i').style.width=(video.duration?video.currentTime/video.duration*100:0)+'%';};setInterval(save,15000);
