window.__tvRemote=function(key,repeat){
 if(key==='back'){var now=Date.now();if(repeat||now-lastBackAt<350)return true;lastBackAt=now;}
 if(liveActive)return liveRemote(key,repeat);
 if(playing&&playbackControls.handle(key,repeat))return true;
 if(key==='back')return back();
 if(playing)return false;
 var active=document.activeElement;if(active&&active.tagName==='INPUT'&&(key==='left'||key==='right'||key==='enter'))return false;
 if(key==='enter'){if(active&&active.tagName==='BUTTON'){active.click();return true;}return false;}
 var row=+(active.dataset&&active.dataset.row||0),col=+(active.dataset&&active.dataset.col||0);if(key==='left')col--;else if(key==='right')col++;else if(key==='up')row--;else if(key==='down')row++;else return false;
 var rows=Array.prototype.slice.call(document.querySelectorAll('[data-row]')).map(function(b){return +b.dataset.row;});if(rows.indexOf(row)<0){var dir=key==='up'?-1:1;for(var tries=0;tries<50&&rows.indexOf(row)<0;tries++)row+=dir;}focus(row,Math.max(0,col));return true;
};
window.addEventListener('keydown',function(e){if(e.target&&/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;var keys={13:'enter',23:'enter',37:'left',38:'up',39:'right',40:'down',32:'play',27:'back',179:'play',227:'rewind',228:'forward'};if(keys[e.keyCode]&&window.__tvRemote(keys[e.keyCode],e.repeat)){e.preventDefault();e.stopImmediatePropagation();}},true);
window.addEventListener('keyup',function(e){if(playing&&!liveActive&&[37,39,227,228].indexOf(e.keyCode)>=0)playbackControls.release();},true);
